package com.dash;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(DashConfig.GROUP)
public interface DashConfig extends Config
{
	String GROUP = "dash";
	String KEY_WIDTH = "width";
	String KEY_POSITION = "position";
	String KEY_CORNER = "corner";

	@ConfigSection(name = "Showing", description = "When the Dash window appears", position = 0)
	String showing = "showing";

	@ConfigSection(name = "Window", description = "Where it goes and what it looks like", position = 1)
	String window = "window";

	@ConfigSection(name = "Tiles", description = "What the window shows, top to bottom", position = 2)
	String tiles = "tiles";

	@ConfigItem(keyName = "mode", name = "Show", description = "Always: on screen the whole time. Only when unfocused: appears when RuneLite is not the active window and goes when it is again. Only with hotkey: shown and hidden by the hotkey alone", section = showing, position = 0)
	default DashMode mode()
	{
		return DashMode.ALWAYS;
	}

	@ConfigItem(keyName = "delay", name = "Show after", description = "When showing only while RuneLite is not the active window: how long it must be unfocused before the window appears", section = showing, position = 1)
	@Units(Units.MILLISECONDS)
	@Range(max = 10000)
	default int delay()
	{
		return 1000;
	}

	@ConfigItem(keyName = "hotkey", name = "Show / hide hotkey", description = "Shows the window, or hides it. Only works while RuneLite is the active window - other programs keep their own shortcuts", section = showing, position = 2)
	default Keybind hotkey()
	{
		return new Keybind(KeyEvent.VK_D, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(keyName = "clickAction", name = "On click", description = "What a click on the Dash window does. Dragging always moves it", section = showing, position = 3)
	default ClickAction clickAction()
	{
		return ClickAction.NOTHING;
	}

	@ConfigItem(keyName = "dimWhenFocused", name = "Dim when RuneLite is active", description = "Fade the window while RuneLite is the active window, since the game itself is in view then", section = showing, position = 4)
	default boolean dimWhenFocused()
	{
		return true;
	}

	@ConfigItem(keyName = KEY_CORNER, name = "Corner", description = "Which corner of the screen the window sits in, until you drag it somewhere else", section = window, position = 0)
	default Corner corner()
	{
		return Corner.TOP_RIGHT;
	}

	@ConfigItem(keyName = "avoidClient", name = "Keep off RuneLite", description = "When the RuneLite window is on that screen, use a corner beside it if there is one", section = window, position = 1)
	default boolean avoidClient()
	{
		return true;
	}

	@ConfigItem(keyName = "margin", name = "Margin", description = "Gap between the window and the edge of the screen", section = window, position = 2)
	@Units(Units.PIXELS)
	@Range(max = 200)
	default int margin()
	{
		return 16;
	}

	@ConfigItem(keyName = KEY_WIDTH, name = "Width", description = "Width of the window; the height follows its contents. Scrolling over the window changes this too", section = window, position = 3)
	@Units(Units.PIXELS)
	@Range(min = DashGeometry.MIN_WIDTH, max = DashGeometry.MAX_WIDTH)
	default int width()
	{
		return 280;
	}

	@ConfigItem(keyName = "opacity", name = "Opacity", description = "How solid the window is", section = window, position = 4)
	@Units(Units.PERCENT)
	@Range(min = 20, max = 100)
	default int opacity()
	{
		return 100;
	}

	@ConfigItem(keyName = "textSize", name = "Text size", description = "How large the text is", section = window, position = 5)
	default TextSize textSize()
	{
		return TextSize.NORMAL;
	}

	@ConfigItem(keyName = "showVitals", name = "Vitals", description = "Hitpoints, prayer, run energy and special attack, with poison and venom", section = tiles, position = 0)
	default boolean showVitals()
	{
		return true;
	}

	@ConfigItem(keyName = "showStatus", name = "Status", description = "World and its type, who you are logged in as, whether you are idle, in combat or skulled", section = tiles, position = 1)
	default boolean showStatus()
	{
		return true;
	}

	@ConfigItem(keyName = "showOffers", name = "Grand Exchange", description = "Every slot with an offer in it, and how far along it is", section = tiles, position = 2)
	default boolean showOffers()
	{
		return true;
	}

	@ConfigItem(keyName = "showAlerts", name = "Alerts", description = "The last few things worth knowing about: being attacked, low hitpoints, an offer finishing, a level up, a private message, or any RuneLite notification, with how long ago each arrived", section = tiles, position = 3)
	default boolean showAlerts()
	{
		return true;
	}

	@ConfigItem(keyName = "showTimers", name = "Timers and boosts", description = "Everything RuneLite is showing as an infobox: timers, stat boosts, counters", section = tiles, position = 4)
	default boolean showTimers()
	{
		return true;
	}

	@ConfigItem(keyName = "showSession", name = "Session", description = "Time logged in and experience gained since, with the rate for the skills that gained most", section = tiles, position = 5)
	default boolean showSession()
	{
		return true;
	}

	@ConfigItem(keyName = "showInventory", name = "Inventory", description = "Free slots and coins carried", section = tiles, position = 6)
	default boolean showInventory()
	{
		return true;
	}

	@ConfigItem(keyName = "showLogout", name = "Six hour logout", description = "Time until the game logs you out for having been logged in six hours", section = tiles, position = 7)
	default boolean showLogout()
	{
		return true;
	}

	@ConfigItem(keyName = "alertCount", name = "Alerts to keep", description = "How many recent alerts the Alerts tile lists", section = tiles, position = 8)
	@Range(min = 1, max = 10)
	default int alertCount()
	{
		return 4;
	}

	/** "x,y" of where the window was last dragged to, or empty to use the corner. */
	@ConfigItem(keyName = KEY_POSITION, name = "", description = "", hidden = true)
	default String position()
	{
		return "";
	}
}

package com.dash;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.WorldType;

/** Text the tiles show. Pure functions, so they are tested. */
final class DashFormat
{
	/** The poison varp counts up into venom at this value; below zero means immune. */
	static final int VENOM_THRESHOLD = 1_000_000;
	static final long SIX_HOURS_MS = 6L * 60 * 60 * 1000;

	private DashFormat()
	{
	}

	enum Poison
	{
		NONE, POISONED, VENOMED, IMMUNE
	}

	static Poison poison(int varp)
	{
		if (varp >= VENOM_THRESHOLD) return Poison.VENOMED;
		if (varp > 0) return Poison.POISONED;
		if (varp < 0) return Poison.IMMUNE;
		return Poison.NONE;
	}

	/** "1h 05m", "12m 03s", "45s". Never negative. */
	static String duration(long millis)
	{
		long seconds = Math.max(0, millis / 1000);
		long hours = seconds / 3600;
		long minutes = (seconds % 3600) / 60;
		long rest = seconds % 60;
		if (hours > 0) return hours + "h " + pad(minutes) + "m";
		if (minutes > 0) return minutes + "m " + pad(rest) + "s";
		return rest + "s";
	}

	/** "4:12:07" or "12:07", for a countdown that is watched. */
	static String clock(long millis)
	{
		long seconds = Math.max(0, millis / 1000);
		long hours = seconds / 3600;
		long minutes = (seconds % 3600) / 60;
		long rest = seconds % 60;
		if (hours > 0) return hours + ":" + pad(minutes) + ":" + pad(rest);
		return minutes + ":" + pad(rest);
	}

	private static String pad(long value)
	{
		return value < 10 ? "0" + value : String.valueOf(value);
	}

	/** "999", "12.3K", "1.20M", "2.5B": the game's own shorthand. */
	static String shortNumber(long value)
	{
		long magnitude = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		if (magnitude < 10_000) return sign + magnitude;
		if (magnitude < 1_000_000) return sign + oneDecimal(magnitude / 1_000d) + "K";
		if (magnitude < 1_000_000_000L) return sign + twoDecimals(magnitude / 1_000_000d) + "M";
		return sign + twoDecimals(magnitude / 1_000_000_000d) + "B";
	}

	private static String oneDecimal(double value)
	{
		String text = String.format("%.1f", value);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}

	private static String twoDecimals(double value)
	{
		String text = String.format("%.2f", value);
		if (text.endsWith("00")) return text.substring(0, text.length() - 3);
		if (text.endsWith("0")) return text.substring(0, text.length() - 1);
		return text;
	}

	/** "1,234,567" */
	static String commas(long value)
	{
		return String.format("%,d", value);
	}

	/** Experience per hour for {@code gained} over {@code millis}; zero until a minute has passed. */
	static long perHour(long gained, long millis)
	{
		if (millis < 60_000 || gained <= 0) return 0;
		return Math.round(gained * 3_600_000d / millis);
	}

	/** Short labels for the kinds of world that matter when you are about to do something there. */
	static List<String> worldTags(EnumSet<WorldType> types)
	{
		List<String> tags = new ArrayList<>();
		if (types == null) return tags;
		tags.add(types.contains(WorldType.MEMBERS) ? "Members" : "Free");
		if (types.contains(WorldType.PVP)) tags.add("PvP");
		if (types.contains(WorldType.HIGH_RISK)) tags.add("High risk");
		if (types.contains(WorldType.BOUNTY)) tags.add("Bounty");
		if (types.contains(WorldType.DEADMAN)) tags.add("Deadman");
		if (types.contains(WorldType.SEASONAL)) tags.add("Seasonal");
		if (types.contains(WorldType.FRESH_START_WORLD)) tags.add("Fresh start");
		if (types.contains(WorldType.SKILL_TOTAL)) tags.add("Total level");
		if (types.contains(WorldType.QUEST_SPEEDRUNNING)) tags.add("Speedrun");
		if (types.contains(WorldType.LAST_MAN_STANDING)) tags.add("LMS");
		if (types.contains(WorldType.PVP_ARENA)) tags.add("PvP Arena");
		if (types.contains(WorldType.TOURNAMENT_WORLD)) tags.add("Tournament");
		if (types.contains(WorldType.BETA_WORLD)) tags.add("Beta");
		return tags;
	}

	/** A world type that a player could be hurt by hopping into without noticing. */
	static boolean dangerous(EnumSet<WorldType> types)
	{
		return types != null && (types.contains(WorldType.PVP) || types.contains(WorldType.HIGH_RISK)
			|| types.contains(WorldType.DEADMAN) || types.contains(WorldType.BOUNTY));
	}

	/** Strips the light HTML RuneLite tooltips carry: line breaks become " · ", tags go. */
	static String plainText(String text)
	{
		if (text == null) return "";
		return text.replaceAll("(?i)<br\\s*/?>", " · ").replaceAll("(?i)</?br>", " · ")
			.replaceAll("<[^>]*>", "").replace("&nbsp;", " ").trim();
	}
}

package com.dash;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Comparator;

/** Where the Dash window goes. Pure arithmetic, so it is tested. */
final class DashGeometry
{
	static final int MIN_WIDTH = 200;
	static final int MAX_WIDTH = 800;

	private DashGeometry()
	{
	}

	static int clampWidth(int width)
	{
		return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, width));
	}

	/** The top-left point that puts a window of {@code size} in the given corner of the work area. */
	static Point place(Corner corner, int margin, Rectangle workArea, Dimension size)
	{
		int x = corner.isLeft() ? workArea.x + margin : workArea.x + workArea.width - size.width - margin;
		int y = corner.isTop() ? workArea.y + margin : workArea.y + workArea.height - size.height - margin;
		return clamp(new Point(x, y), size, workArea);
	}

	/**
	 * Like {@link #place}, but prefers a corner where the window would not sit on top of
	 * {@code avoid} - the RuneLite window, when it is on the same screen. The preferred corner wins
	 * if it is clear; otherwise the first clear corner going round; otherwise the preferred corner
	 * anyway.
	 */
	static Point place(Corner preferred, int margin, Rectangle workArea, Dimension size, Rectangle avoid)
	{
		Point first = place(preferred, margin, workArea, size);
		if (avoid == null || !new Rectangle(first, size).intersects(avoid)) return first;
		// Slide along the same edge before jumping to the other one.
		Corner[] fallbacks = Arrays.copyOf(Corner.values(), Corner.values().length);
		Arrays.sort(fallbacks, Comparator.comparingInt((Corner corner) -> corner.isTop() == preferred.isTop() ? 0 : 1)
			.thenComparingInt(corner -> corner.isLeft() == preferred.isLeft() ? 0 : 1));
		for (Corner corner : fallbacks)
		{
			if (corner == preferred) continue;
			Point candidate = place(corner, margin, workArea, size);
			if (!new Rectangle(candidate, size).intersects(avoid)) return candidate;
		}
		return first;
	}

	/** Keeps a window on screen: fully visible if it fits, pinned to the top-left if it does not. */
	static Point clamp(Point point, Dimension size, Rectangle workArea)
	{
		int maxX = workArea.x + workArea.width - size.width;
		int maxY = workArea.y + workArea.height - size.height;
		int x = Math.max(workArea.x, Math.min(point.x, maxX));
		int y = Math.max(workArea.y, Math.min(point.y, maxY));
		return new Point(x, y);
	}

	/**
	 * Where a window that was at {@code location} with {@code oldSize} should go now that it is
	 * {@code newSize}: a window in a bottom corner grows upwards, one in a right corner grows leftwards,
	 * so the edge nearest the screen edge stays put.
	 */
	static Point regrow(Point location, Dimension oldSize, Dimension newSize, Rectangle workArea)
	{
		int centreX = location.x + oldSize.width / 2;
		int centreY = location.y + oldSize.height / 2;
		boolean right = centreX > workArea.x + workArea.width / 2;
		boolean bottom = centreY > workArea.y + workArea.height / 2;
		int x = right ? location.x + oldSize.width - newSize.width : location.x;
		int y = bottom ? location.y + oldSize.height - newSize.height : location.y;
		return clamp(new Point(x, y), newSize, workArea);
	}

	/** Reads an "x,y" position saved by {@link #formatPosition}; null for anything else. */
	static Point parsePosition(String text)
	{
		if (text == null) return null;
		String[] parts = text.trim().split(",");
		if (parts.length != 2) return null;
		try
		{
			return new Point(Integer.parseInt(parts[0].trim()), Integer.parseInt(parts[1].trim()));
		}
		catch (NumberFormatException exception)
		{
			return null;
		}
	}

	static String formatPosition(Point point)
	{
		return point.x + "," + point.y;
	}

	/** A new width after a scroll of {@code notches}: ten percent per notch, within the limits. */
	static int scrolledWidth(int width, int notches)
	{
		double factor = Math.pow(1.1, -notches);
		return clampWidth((int) Math.round(width * factor));
	}
}

package com.dash;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum DashMode
{
	ALWAYS("Always"),
	WHEN_UNFOCUSED("Only when unfocused"),
	HOTKEY_ONLY("Only with hotkey");

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.dash;

import com.google.inject.Provides;
import java.awt.Dimension;
import java.awt.Frame;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsDevice;
