@Slf4j
@PluginDescriptor(
	name = "Dash",
	description = "A small always-on-top window of your vitals, Grand Exchange offers, timers and alerts for a second monitor or beside another app",
	tags = {"dashboard", "window", "always on top", "second monitor", "afk", "grand exchange", "vitals", "timers"}
)
public class DashPlugin extends Plugin
{
	private static final int INVENTORY_SLOTS = 28;
	private static final int MAX_ALERTS = 10;
	private static final int TOP_GAINS = 3;
	/** How often to look again while RuneLite is unfocused but probably still in view. */
	private static final int RECHECK_MS = 1000;
	/** The window fades to this share of its opacity while RuneLite is the active window. */
	private static final float DIM = 0.55f;
	/** Hitpoints at or below this share of the maximum raise an alert, once per dip. */
	private static final int LOW_HITPOINTS_PERCENT = 25;
	private static final String LEVEL_UP = "Congratulations, you've just advanced";

	@Inject private Client client;
	@Inject private DashConfig config;
	@Inject private ConfigManager configManager;
	@Inject private KeyManager keyManager;
	@Inject private ItemManager itemManager;
	@Inject private InfoBoxManager infoBoxManager;

	private final HotkeyListener hotkey = new HotkeyListener(() -> config.hotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			SwingUtilities.invokeLater(DashPlugin.this::toggle);
		}
	};
	private final WindowFocusListener focusListener = new WindowFocusListener()
	{
		@Override
		public void windowGainedFocus(WindowEvent event)
		{
			clientFocused();
		}

		@Override
		public void windowLostFocus(WindowEvent event)
		{
			clientUnfocused();
		}
	};

	// Swing thread state.
	private DashWindow window;
	private Window clientWindow;
	private Timer showTimer;
	private boolean pinned;
	private boolean autoShown;
	/** Set when the user dismissed the window; it waits for RuneLite to be focused again first. */
	private boolean dismissed;
	private boolean focused = true;

	// Client thread state.
	private final Deque<DashSnapshot.Alert> alerts = new ArrayDeque<>();
	private final Map<Integer, AsyncBufferedImage> icons = new HashMap<>();
	private final Map<Skill, Integer> startXp = new EnumMap<>(Skill.class);
	private long sessionStartedAt;
	private long loginAt;
	private long lastActiveAt;
	private long attackedAt;
	private boolean lowHitpoints;
	private final Map<Integer, GrandExchangeOfferState> offerStates = new HashMap<>();
	private WorldPoint lastPosition;
	private int lastAnimation = -1;

	@Override
	protected void startUp()
	{
		keyManager.registerKeyListener(hotkey);
		SwingUtilities.invokeLater(() ->
		{
			window = new DashWindow(config, this::clicked, this::hide, this::scrolled, this::moved, this::heightChanged);
			showTimer = new Timer(RECHECK_MS, event -> autoShow());
			showTimer.setRepeats(true);
			applyWindowConfig();
			attachToClientWindow();
			updateVisibility();
		});
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkey);
		alerts.clear();
		icons.clear();
		resetSession();
		SwingUtilities.invokeLater(() ->
		{
			if (showTimer != null) showTimer.stop();
			if (clientWindow != null) clientWindow.removeWindowFocusListener(focusListener);
			if (window != null) window.dispose();
			window = null;
			clientWindow = null;
			showTimer = null;
			pinned = false;
			autoShown = false;
			dismissed = false;
			focused = true;
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// The canvas can be parented after the plugin starts; keep trying until the window is found.
		if (clientWindow == null && window != null) SwingUtilities.invokeLater(this::attachToClientWindow);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DashConfig.GROUP.equals(event.getGroup())) return;
		// Picking a corner is a request to go there, so a dragged position no longer applies.
		if (DashConfig.KEY_CORNER.equals(event.getKey())) configManager.unsetConfiguration(DashConfig.GROUP, DashConfig.KEY_POSITION);
		SwingUtilities.invokeLater(() ->
		{
			applyWindowConfig();
			updateVisibility();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
				resetSession();
				publish();
				break;
			case LOGGING_IN:
				resetSession();
				break;
			case HOPPING:
				// A hop starts the six hour clock again but is the same session.
				loginAt = 0;
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The first tick after a login or hop starts the clocks; the plugin may also have been
		// switched on mid-session, in which case now is the best guess there is.
		long now = System.currentTimeMillis();
		if (loginAt == 0) loginAt = now;
		if (sessionStartedAt == 0) sessionStartedAt = now;
		trackActivity();
		checkHitpoints();
		publish();
	}

	private void checkHitpoints()
	{
		int max = client.getRealSkillLevel(Skill.HITPOINTS);
		int current = client.getBoostedSkillLevel(Skill.HITPOINTS);
		boolean low = max > 0 && current * 100 <= LOW_HITPOINTS_PERCENT * max;
		if (low && !lowHitpoints) remember("Hitpoints low: " + current + " / " + max);
		lowHitpoints = low;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player me = client.getLocalPlayer();
		if (event.getActor() != me) return;
		Actor attacker = me.getInteracting();
		attacked(attacker != null && attacker != me ? attacker : null);
	}

	/** A hit or a hostile target a while after the last one is a new fight, and worth an alert. */
	private void attacked(Actor by)
	{
		long now = System.currentTimeMillis();
		boolean fresh = now - attackedAt >= DashTiles.ATTACK_MEMORY_MS;
		attackedAt = now;
		if (!fresh) return;
		String name = by != null && by.getName() != null ? Text.removeTags(by.getName()) : null;
		remember(name != null ? "Under attack by " + name : "Under attack");
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Player me = client.getLocalPlayer();
		if (me == null || event.getTarget() != me || event.getSource() == me) return;
		// A shopkeeper or clerk turns to face you too; only something that can fight counts.
		Actor source = event.getSource();
		boolean hostile = source instanceof Player || (source instanceof NPC && ((NPC) source).getCombatLevel() > 0);
		if (hostile) attacked(source);
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer offer = event.getOffer();
		GrandExchangeOfferState state = offer.getState();
		// Every slot reports its state on login; only a change seen while watching is news.
		GrandExchangeOfferState previous = offerStates.put(event.getSlot(), state);
		if (previous == null || previous == state) return;
		if (state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.SOLD)
		{
			String name = itemManager.getItemComposition(offer.getItemId()).getName();
			String verb = state == GrandExchangeOfferState.BOUGHT ? "Bought " : "Sold ";
			remember(verb + DashFormat.commas(offer.getTotalQuantity()) + " " + name);
		}
	}

	@Subscribe
	public void onNotificationFired(NotificationFired event)
	{
		if (event.getMessage() != null) remember(event.getMessage());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type == ChatMessageType.GAMEMESSAGE && event.getMessage() != null && event.getMessage().contains(LEVEL_UP))
		{
			remember(Text.removeTags(event.getMessage()));
			return;
		}
		if (type != ChatMessageType.PRIVATECHAT && type != ChatMessageType.MODPRIVATECHAT) return;
		String from = Text.removeTags(event.getName());
		remember("PM from " + from + ": " + Text.removeTags(event.getMessage()));
	}

	private void remember(String text)
	{
		alerts.addFirst(new DashSnapshot.Alert(System.currentTimeMillis(), text));
		while (alerts.size() > MAX_ALERTS) alerts.removeLast();
		publish();
	}

	private void resetSession()
	{
		sessionStartedAt = 0;
		loginAt = 0;
		startXp.clear();
		lastActiveAt = 0;
		attackedAt = 0;
		lowHitpoints = false;
		offerStates.clear();
		lastPosition = null;
		lastAnimation = -1;
	}

	/** Anything the player does - moving, animating, interacting - counts as being active. */
	private void trackActivity()
	{
		Player me = client.getLocalPlayer();
		if (me == null) return;
		long now = System.currentTimeMillis();
		WorldPoint position = me.getWorldLocation();
		int animation = me.getAnimation();
		boolean moved = lastPosition != null && !lastPosition.equals(position);
		boolean animating = animation != -1 && animation != lastAnimation;
		if (moved || animating || me.getInteracting() != null || lastActiveAt == 0) lastActiveAt = now;
		lastPosition = position;
		lastAnimation = animation;
	}

	/** Reads everything on the client thread and hands the window an immutable copy. */
	private void publish()
	{
		DashWindow target = window;
		if (target == null) return;
		target.show(snapshot());
	}

	private DashSnapshot snapshot()
	{
		long now = System.currentTimeMillis();
		DashSnapshot.DashSnapshotBuilder b = DashSnapshot.builder().takenAt(now).alerts(new ArrayList<>(alerts));
		Player me = client.getLocalPlayer();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN && me != null;
		b.loggedIn(loggedIn);
		if (!loggedIn) return b.build();

		b.hitpoints(client.getBoostedSkillLevel(Skill.HITPOINTS)).maxHitpoints(client.getRealSkillLevel(Skill.HITPOINTS))
			.prayer(client.getBoostedSkillLevel(Skill.PRAYER)).maxPrayer(client.getRealSkillLevel(Skill.PRAYER))
			.runEnergy(client.getEnergy() / 100).special(client.getVarpValue(VarPlayerID.SA_ENERGY) / 10)
			.poison(DashFormat.poison(client.getVarpValue(VarPlayerID.POISON)));

		b.world(client.getWorld()).worldTags(DashFormat.worldTags(client.getWorldType()))
			.dangerousWorld(DashFormat.dangerous(client.getWorldType()))
			.playerName(me.getName()).combatLevel(me.getCombatLevel()).skulled(me.getSkullIcon() != -1)
			.lastActiveAt(lastActiveAt).attackedAt(attackedAt);
		Actor target = me.getInteracting();
		if (target != null && target.getName() != null && fighting(me, target, now)) b.fighting(Text.removeTags(target.getName()));

		b.offers(offers());
		b.boxes(boxes());
		session(b, now);

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			int used = 0;
			for (Item item : inventory.getItems())
			{
				if (item.getId() > 0) used++;
			}
			b.freeSlots(Math.max(0, INVENTORY_SLOTS - used)).coins(inventory.count(ItemID.COINS));
		}
		b.loginAt(loginAt);
		return b.build();
	}

	/**
	 * Interacting with something is not fighting it: clerks, bankers and quest NPCs are interacted
	 * with too. It is a fight when the other side can fight and is engaging back, or has hit us.
	 */
	private boolean fighting(Player me, Actor target, long now)
	{
		boolean canFight = target instanceof Player || (target instanceof NPC && ((NPC) target).getCombatLevel() > 0);
		if (!canFight) return false;
		return target.getInteracting() == me || now - attackedAt < DashTiles.ATTACK_MEMORY_MS;
	}

	private List<DashSnapshot.Offer> offers()
	{
		List<DashSnapshot.Offer> offers = new ArrayList<>();
		GrandExchangeOffer[] slots = client.getGrandExchangeOffers();
		if (slots == null) return offers;
		for (int slot = 0; slot < slots.length; slot++)
		{
			GrandExchangeOffer offer = slots[slot];
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY || offer.getItemId() <= 0) continue;
			GrandExchangeOfferState state = offer.getState();
			boolean buying = state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT
				|| state == GrandExchangeOfferState.CANCELLED_BUY;
			String name = itemManager.getItemComposition(offer.getItemId()).getName();
			offers.add(new DashSnapshot.Offer(slot, name, icon(offer.getItemId()), buying,
				offer.getQuantitySold(), offer.getTotalQuantity(), offer.getPrice(), state));
		}
		return offers;
	}

	private AsyncBufferedImage icon(int itemId)
	{
		AsyncBufferedImage image = icons.get(itemId);
		if (image == null)
		{
			image = itemManager.getImage(itemId);
			icons.put(itemId, image);
			image.onLoaded(() ->
			{
				DashWindow target = window;
				if (target != null) target.repaint();
			});
		}
		return image;
	}

	/** Every infobox RuneLite is showing, as the picture, text and name it gives them. */
	private List<DashSnapshot.Box> boxes()
	{
		List<DashSnapshot.Box> boxes = new ArrayList<>();
		for (InfoBox box : infoBoxManager.getInfoBoxes())
		{
			if (!box.render()) continue;
			String name = DashFormat.plainText(box.getTooltip());
			if (name.isEmpty()) name = box.getName() == null ? "" : box.getName();
			int cut = name.indexOf(" · ");
			if (cut > 0) name = name.substring(0, cut);
			boxes.add(new DashSnapshot.Box(name, box.getText(), box.getTextColor(), box.getImage()));
		}
		return boxes;
	}

	// OVERALL is deprecated but still in values(), and it is not a skill to measure.
	@SuppressWarnings("deprecation")
	private void session(DashSnapshot.DashSnapshotBuilder b, long now)
	{
		if (sessionStartedAt == 0) return;
		if (startXp.isEmpty())
		{
			// Experience arrives a moment after login; until it has, there is nothing to measure from.
			long total = 0;
			for (Skill skill : Skill.values())
			{
				if (skill == Skill.OVERALL) continue;
				int xp = client.getSkillExperience(skill);
				total += xp;
				startXp.put(skill, xp);
			}
			if (total == 0) startXp.clear();
		}
		long gained = 0;
		List<DashSnapshot.SkillGain> gains = new ArrayList<>();
		long elapsed = now - sessionStartedAt;
		for (Map.Entry<Skill, Integer> entry : startXp.entrySet())
		{
			long delta = client.getSkillExperience(entry.getKey()) - entry.getValue();
			if (delta <= 0) continue;
			gained += delta;
			gains.add(new DashSnapshot.SkillGain(entry.getKey().getName(), delta, DashFormat.perHour(delta, elapsed)));
		}
		gains.sort(Comparator.comparingLong(DashSnapshot.SkillGain::getGained).reversed());
		b.sessionStartedAt(sessionStartedAt).xpGained(gained).topGains(gains.subList(0, Math.min(TOP_GAINS, gains.size())));
	}

	// Window management, Swing thread from here on.

	private void attachToClientWindow()
	{
		if (clientWindow != null || client.getCanvas() == null) return;
		Window found = SwingUtilities.getWindowAncestor(client.getCanvas());
		if (found == null) return;
		clientWindow = found;
		clientWindow.addWindowFocusListener(focusListener);
		// The window may have been placed before RuneLite's own window existed, on the wrong screen.
		if (window.isVisible()) position();
		if (!clientWindow.isFocused()) clientUnfocused();
	}

	private void clientFocused()
	{
		focused = true;
		if (showTimer != null) showTimer.stop();
		autoShown = false;
		if (config.mode() != DashMode.ALWAYS) dismissed = false;
		applyOpacity();
		updateVisibility();
	}

	private void clientUnfocused()
	{
		focused = false;
		applyOpacity();
		if (config.mode() != DashMode.WHEN_UNFOCUSED || dismissed || showTimer == null) return;
		showTimer.setInitialDelay(config.delay());
		showTimer.restart();
	}

	private void autoShow()
	{
		// Focus may have gone to another RuneLite window - a config dialog, say - rather than away.
		if (clientWindow == null || clientWindow.isFocused() || anyOwnWindowFocused()) return;
		if (config.mode() != DashMode.WHEN_UNFOCUSED || dismissed) return;
		showTimer.stop();
		autoShown = true;
		updateVisibility();
	}

	/** Whether one of the client's own dialogs has focus rather than another program. */
	private boolean anyOwnWindowFocused()
	{
		for (Window owned : clientWindow.getOwnedWindows())
		{
			if (owned.isFocused()) return true;
		}
		return false;
	}

	/** The hotkey: shows the window if it is hidden, hides it if it is showing. */
	private void toggle()
	{
		if (window == null) return;
		if (window.isVisible())
		{
			hide();
			return;
		}
		dismissed = false;
		pinned = config.mode() != DashMode.ALWAYS;
		updateVisibility();
	}

	private void updateVisibility()
	{
		if (window == null) return;
		boolean visible;
		switch (config.mode())
		{
			case ALWAYS:
				visible = !dismissed;
				break;
			case WHEN_UNFOCUSED:
				visible = pinned || autoShown;
				break;
			default:
				visible = pinned;
				break;
		}
		if (visible && !window.isVisible())
		{
			position();
			window.setVisible(true);
		}
		else if (!visible && window.isVisible())
		{
			window.setVisible(false);
		}
	}

	private void applyWindowConfig()
	{
		if (window == null) return;
		applyOpacity();
		if (config.mode() != DashMode.WHEN_UNFOCUSED) autoShown = false;
		if (config.mode() != DashMode.HOTKEY_ONLY && config.mode() != DashMode.WHEN_UNFOCUSED) pinned = false;
		if (window.isVisible()) position();
	}

	private void applyOpacity()
	{
		if (window == null) return;
		int opacity = config.opacity();
		if (focused && config.dimWhenFocused() && config.mode() == DashMode.ALWAYS) opacity = Math.round(opacity * DIM);
		window.setOpacityPercent(opacity);
	}

	private void position()
	{
		Dimension size = window.sizeFor(DashGeometry.clampWidth(config.width()));
		Point custom = DashGeometry.parsePosition(config.position());
		Point location;
		if (custom != null)
		{
			// A dragged window stays on whichever screen it was dragged to.
			location = DashGeometry.clamp(custom, size, workArea(screenContaining(custom)));
		}
		else
		{
			location = DashGeometry.place(config.corner(), config.margin(), workArea(clientScreen()), size, clientBounds());
		}
		window.setSize(size);
		window.setLocation(location);
		log.debug("Dash window at {} size {} on screen {}", location, size, workArea(screenContaining(location)));
	}

	/** The contents changed height; keep the edge nearest the screen edge where it was. */
	private void heightChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window == null || !window.isVisible()) return;
			Dimension old = window.getSize();
			Dimension size = window.sizeFor(old.width);
			if (size.equals(old)) return;
			Point custom = DashGeometry.parsePosition(config.position());
			Rectangle area = workArea(screenContaining(window.getLocation()));
			Point location = custom != null
				? DashGeometry.regrow(window.getLocation(), old, size, area)
				: DashGeometry.place(config.corner(), config.margin(), workArea(clientScreen()), size, clientBounds());
			window.setSize(size);
			window.setLocation(location);
		});
	}

	/** Where the RuneLite window is, or null when it is minimised or not to be avoided. */
	private Rectangle clientBounds()
	{
		if (!config.avoidClient() || clientWindow == null || !clientWindow.isShowing()) return null;
		if (clientWindow instanceof Frame && (((Frame) clientWindow).getExtendedState() & Frame.ICONIFIED) != 0) return null;
		return clientWindow.getBounds();
	}

	private GraphicsConfiguration clientScreen()
	{
		return clientWindow != null ? clientWindow.getGraphicsConfiguration() : window.getGraphicsConfiguration();
	}

	private GraphicsConfiguration screenContaining(Point point)
	{
		for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
		{
			GraphicsConfiguration graphics = device.getDefaultConfiguration();
			if (graphics.getBounds().contains(point)) return graphics;
		}
		return clientScreen();
	}

	/** The usable area of a screen, taskbar excluded. */
	private static Rectangle workArea(GraphicsConfiguration graphics)
	{
		Rectangle bounds = graphics.getBounds();
		Insets insets = Toolkit.getDefaultToolkit().getScreenInsets(graphics);
		return new Rectangle(bounds.x + insets.left, bounds.y + insets.top,
			bounds.width - insets.left - insets.right, bounds.height - insets.top - insets.bottom);
	}

	private void clicked()
	{
		if (config.clickAction() == ClickAction.HIDE_DASH) hide();
	}

	/** Hides the window. In always mode the hotkey brings it back; otherwise focusing RuneLite does. */
	private void hide()
	{
		pinned = false;
		autoShown = false;
		dismissed = true;
		updateVisibility();
	}

	private void scrolled(int notches)
	{
		int width = DashGeometry.scrolledWidth(config.width(), notches);
		if (width != config.width()) configManager.setConfiguration(DashConfig.GROUP, DashConfig.KEY_WIDTH, width);
	}

	private void moved(Point location)
	{
		configManager.setConfiguration(DashConfig.GROUP, DashConfig.KEY_POSITION, DashGeometry.formatPosition(location));
	}

	@Provides
	DashConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DashConfig.class);
	}
}

package com.dash;

import java.awt.Color;
import java.awt.Image;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Everything the window shows, read on the client thread once a tick and handed to the Swing
 * thread whole. Immutable, so the two threads never share anything that changes.
 */
@Value
@Builder
class DashSnapshot
{
	long takenAt;
	boolean loggedIn;

	// Vitals.
	int hitpoints;
	int maxHitpoints;
	int prayer;
	int maxPrayer;
	/** 0 to 100. */
	int runEnergy;
	/** 0 to 100. */
	int special;
	@Builder.Default
	DashFormat.Poison poison = DashFormat.Poison.NONE;

	// Status.
	int world;
	@Builder.Default
	List<String> worldTags = Collections.emptyList();
	boolean dangerousWorld;
	String playerName;
	int combatLevel;
	boolean skulled;
	/** When the player last did anything; 0 when unknown. */
	long lastActiveAt;
	/** What the player is interacting with, or null. */
	String fighting;
	/** When something last hit or targeted the player; 0 when never. */
	long attackedAt;

	@Builder.Default
	List<Offer> offers = Collections.emptyList();
	@Builder.Default
	List<Alert> alerts = Collections.emptyList();
	@Builder.Default
	List<Box> boxes = Collections.emptyList();

	// Session.
	/** 0 when not logged in. */
	long sessionStartedAt;
	long xpGained;
	@Builder.Default
	List<SkillGain> topGains = Collections.emptyList();

	// Inventory.
	int freeSlots;
	long coins;

	/** When this login (or hop) happened, for the six hour logout; 0 when unknown. */
	long loginAt;

	@Value
	static class Offer
	{
		int slot;
		String itemName;
		/** May still be loading; it repaints itself when it arrives. */
		Image icon;
		boolean buying;
		int done;
		int total;
		/** Widened to long in RuneLite 1.13.0 for prices past the old signed 32 bit ceiling. */
		long price;
		GrandExchangeOfferState state;

		boolean finished()
		{
			return state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.SOLD;
		}

		boolean cancelled()
		{
			return state == GrandExchangeOfferState.CANCELLED_BUY || state == GrandExchangeOfferState.CANCELLED_SELL;
		}
	}

	@Value
	static class Alert
	{
		long at;
		String text;
	}

	/** An infobox as RuneLite draws it: a picture, a bit of text, and a name from its tooltip. */
	@Value
	static class Box
	{
		String name;
		String text;
		Color textColor;
		Image image;
	}

	@Value
	static class SkillGain
	{
		String skill;
		long gained;
		long perHour;
	}
}

package com.dash;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.GrandExchangeOfferState;

/**
 * The tiles, and the little drawing language they share. Each tile says how tall it wants to be
 * for a given width, then paints itself at a y offset. Everything is drawn by hand so the window
 * looks the same on every platform and never takes focus.
 */
final class DashTiles
{
	static final Color BACKGROUND = new Color(20, 20, 20);
	static final Color PANEL = new Color(31, 31, 31);
	static final Color LINE = new Color(52, 52, 52);
	static final Color TEXT = new Color(232, 230, 227);
	static final Color MUTED = new Color(141, 138, 134);
	static final Color HITPOINTS = new Color(255, 70, 70);
	static final Color HITPOINTS_FULL = new Color(90, 200, 120);
	static final Color PRAYER = new Color(80, 155, 255);
	static final Color RUN = new Color(255, 190, 45);
	static final Color SPECIAL = new Color(255, 122, 47);
	static final Color WARN = new Color(255, 90, 90);
	static final Color GOOD = new Color(90, 200, 120);
	static final Color TRACK = new Color(44, 44, 44);
	/** Something that attacked recently is still a fight for this long. */
	static final long ATTACK_MEMORY_MS = 6000;

	private DashTiles()
	{
	}

	/** What every tile paints with. Built once per paint, or once per measure with no graphics. */
	static final class Layout
	{
		final Graphics2D g;
		final int width;
		final int pad;
		final Font font;
		final Font bold;
		final Font small;
		final FontMetrics fm;
		final FontMetrics boldFm;
		final FontMetrics smallFm;
		final int row;
		final DashSnapshot snapshot;
		final DashConfig config;
		final long now;

		Layout(Graphics2D g, int width, Font font, Font bold, Font small, FontMetrics fm, FontMetrics boldFm, FontMetrics smallFm,
			DashSnapshot snapshot, DashConfig config, long now)
		{
			this.g = g;
			this.width = width;
			this.pad = Math.max(6, Math.round(fm.getHeight() * 0.45f));
			this.font = font;
			this.bold = bold;
			this.small = small;
			this.fm = fm;
			this.boldFm = boldFm;
			this.smallFm = smallFm;
			this.row = fm.getHeight() + 4;
			this.snapshot = snapshot;
			this.config = config;
			this.now = now;
		}

		int inner()
		{
			return width - 2 * pad;
		}

		void text(String text, int x, int baseline, Color color, Font with)
		{
			g.setFont(with);
			g.setColor(color);
			g.drawString(text, x, baseline);
		}

		void textRight(String text, int right, int baseline, Color color, Font with)
		{
			g.setFont(with);
			g.setColor(color);
			g.drawString(text, right - g.getFontMetrics().stringWidth(text), baseline);
		}

		/** Cuts text to fit, with an ellipsis. */
		String fit(String text, int maxWidth, FontMetrics with)
		{
			if (text == null) return "";
			if (with.stringWidth(text) <= maxWidth) return text;
			String ellipsis = "…";
			int room = maxWidth - with.stringWidth(ellipsis);
			int end = text.length();
			while (end > 0 && with.stringWidth(text.substring(0, end)) > room) end--;
			return text.substring(0, end).trim() + ellipsis;
		}

		void bar(int x, int y, int width, int height, double fraction, Color fill)
		{
			g.setColor(TRACK);
			g.fillRoundRect(x, y, width, height, height, height);
			int filled = (int) Math.round(width * Math.max(0, Math.min(1, fraction)));
			if (filled > 0)
			{
				g.setColor(fill);
				g.fillRoundRect(x, y, Math.max(filled, height), height, height, height);
			}
		}

		void icon(Image image, int x, int y, int size)
		{
			if (image == null) return;
			int w = image.getWidth(null);
			int h = image.getHeight(null);
			if (w <= 0 || h <= 0) return;
			float scale = Math.min(size / (float) w, size / (float) h);
			int dw = Math.max(1, Math.round(w * scale));
			int dh = Math.max(1, Math.round(h * scale));
			g.drawImage(image, x + (size - dw) / 2, y + (size - dh) / 2, dw, dh, null);
		}
	}

	abstract static class Tile
	{
		abstract String title();

		abstract boolean enabled(DashConfig config);

		/** Height in pixels for this layout. */
		abstract int height(Layout l);

		/** Paints the tile with its top edge at {@code y}. */
		abstract void paint(Layout l, int y);

		/** A tile with a title line and rows under it. */
		int titled(Layout l, int rows)
		{
			return l.pad + l.smallFm.getHeight() + 2 + rows * l.row + l.pad;
		}

		/** Paints the title and returns the y of the first row's top. */
		int paintTitle(Layout l, int y)
		{
			int baseline = y + l.pad + l.smallFm.getAscent();
			l.text(title().toUpperCase(), l.pad, baseline, MUTED, l.small);
			return y + l.pad + l.smallFm.getHeight() + 2;
		}

		/** A one-line tile: label left, value right, no title. */
		int oneLine(Layout l)
		{
			return l.pad + l.row + l.pad / 2;
		}

		void paintOneLine(Layout l, int y, String label, String value, Color valueColor)
		{
			int baseline = y + l.pad / 2 + l.fm.getAscent() + 2;
			l.text(label, l.pad, baseline, MUTED, l.font);
			l.textRight(value, l.width - l.pad, baseline, valueColor, l.bold);
		}

		void paintEmpty(Layout l, int y, String text)
		{
			l.text(text, l.pad, y + l.fm.getAscent() + 2, MUTED, l.font);
		}
	}

	static List<Tile> all()
	{
		List<Tile> tiles = new ArrayList<>();
		tiles.add(new Vitals());
		tiles.add(new Status());
		tiles.add(new Offers());
		tiles.add(new Alerts());
		tiles.add(new Timers());
		tiles.add(new Session());
		tiles.add(new Inventory());
		tiles.add(new Logout());
		return tiles;
	}

	static final class Vitals extends Tile
	{
		@Override
		String title()
		{
			return "Vitals";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showVitals();
		}

		@Override
		int height(Layout l)
		{
			int rows = l.snapshot.getPoison() == DashFormat.Poison.NONE ? 4 : 5;
			return titled(l, rows);
		}

		@Override
		void paint(Layout l, int y)
		{
			DashSnapshot s = l.snapshot;
			int top = paintTitle(l, y);
			int label = l.fm.stringWidth("Spec") + l.pad;
			int barX = l.pad + label;
			int barW = l.inner() - label;
			int barH = l.row - 6;
			Color hp = s.getMaxHitpoints() > 0 && s.getHitpoints() * 4 <= s.getMaxHitpoints() ? HITPOINTS : HITPOINTS_FULL;
			row(l, top, "HP", barX, barW, barH, s.getHitpoints(), s.getMaxHitpoints(), s.getHitpoints() + " / " + s.getMaxHitpoints(), hp);
			row(l, top + l.row, "Pray", barX, barW, barH, s.getPrayer(), s.getMaxPrayer(), s.getPrayer() + " / " + s.getMaxPrayer(), PRAYER);
			row(l, top + 2 * l.row, "Run", barX, barW, barH, s.getRunEnergy(), 100, s.getRunEnergy() + "%", RUN);
			row(l, top + 3 * l.row, "Spec", barX, barW, barH, s.getSpecial(), 100, s.getSpecial() + "%", SPECIAL);
			if (s.getPoison() != DashFormat.Poison.NONE)
			{
				String text = s.getPoison() == DashFormat.Poison.VENOMED ? "Venomed" : s.getPoison() == DashFormat.Poison.POISONED ? "Poisoned" : "Immune to poison";
				Color color = s.getPoison() == DashFormat.Poison.IMMUNE ? MUTED : WARN;
				l.text(text, l.pad, top + 4 * l.row + l.fm.getAscent() + 2, color, l.bold);
			}
		}

		private void row(Layout l, int y, String label, int barX, int barW, int barH, int value, int max, String text, Color color)
		{
			int baseline = y + l.fm.getAscent() + 2;
			l.text(label, l.pad, baseline, MUTED, l.font);
			l.bar(barX, y + 3, barW, barH, max > 0 ? value / (double) max : 0, color);
			l.g.setFont(l.small);
			int width = l.g.getFontMetrics().stringWidth(text);
			l.g.setColor(Color.BLACK);
			l.g.drawString(text, barX + (barW - width) / 2 + 1, y + 3 + (barH + l.smallFm.getAscent()) / 2);
			l.g.setColor(Color.WHITE);
			l.g.drawString(text, barX + (barW - width) / 2, y + 3 + (barH + l.smallFm.getAscent()) / 2 - 1);
		}
	}

	static final class Status extends Tile
	{
		@Override
		String title()
		{
			return "Status";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showStatus();
		}

		@Override
		int height(Layout l)
		{
			return titled(l, l.snapshot.isLoggedIn() ? 3 : 1);
		}

		@Override
		void paint(Layout l, int y)
		{
			DashSnapshot s = l.snapshot;
			int top = paintTitle(l, y);
			if (!s.isLoggedIn())
			{
				paintEmpty(l, top, "Not logged in");
				return;
			}
			int baseline = top + l.fm.getAscent() + 2;
			String world = "World " + s.getWorld();
			l.text(world, l.pad, baseline, TEXT, l.bold);
			String tags = String.join(" · ", s.getWorldTags());
			int x = l.pad + l.boldFm.stringWidth(world) + l.pad;
			l.text(l.fit(tags, l.width - l.pad - x, l.fm), x, baseline, s.isDangerousWorld() ? WARN : MUTED, l.font);

			baseline += l.row;
			String who = s.getPlayerName() == null ? "" : s.getPlayerName();
			if (s.getCombatLevel() > 0) who += "  (" + s.getCombatLevel() + ")";
			l.text(l.fit(who, l.inner(), l.fm), l.pad, baseline, TEXT, l.font);
			if (s.isSkulled()) l.textRight("Skulled", l.width - l.pad, baseline, WARN, l.bold);

			baseline += l.row;
			String activity;
			Color color = MUTED;
			if (s.getAttackedAt() > 0 && l.now - s.getAttackedAt() < ATTACK_MEMORY_MS)
			{
				activity = "Under attack";
				color = WARN;
			}
			else if (s.getFighting() != null)
			{
				activity = "Fighting " + s.getFighting();
				color = TEXT;
			}
			else if (s.getLastActiveAt() > 0 && l.now - s.getLastActiveAt() >= 5000)
			{
				activity = "Idle " + DashFormat.duration(l.now - s.getLastActiveAt());
			}
			else
			{
				activity = "Active";
				color = GOOD;
			}
			l.text(activity, l.pad, baseline, color, l.font);
		}
	}

	static final class Offers extends Tile
	{
		@Override
		String title()
		{
			return "Grand Exchange";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showOffers();
		}

		@Override
		int height(Layout l)
		{
			int count = l.snapshot.getOffers().size();
			return titled(l, count == 0 ? 1 : count * 2);
		}

		@Override
		void paint(Layout l, int y)
		{
			int top = paintTitle(l, y);
			List<DashSnapshot.Offer> offers = l.snapshot.getOffers();
			if (offers.isEmpty())
			{
				paintEmpty(l, top, l.snapshot.isLoggedIn() ? "No offers" : "Not logged in");
				return;
			}
			int icon = l.row + 2;
			for (DashSnapshot.Offer offer : offers)
			{
				int baseline = top + l.fm.getAscent() + 2;
				l.icon(offer.getIcon(), l.pad, top + 1, icon);
				int x = l.pad + icon + 6;
				String state;
				Color stateColor;
				if (offer.finished())
				{
					state = offer.isBuying() ? "Bought" : "Sold";
					stateColor = GOOD;
				}
				else if (offer.cancelled())
				{
					state = "Cancelled";
					stateColor = WARN;
				}
				else
				{
					state = offer.isBuying() ? "Buying" : "Selling";
					stateColor = MUTED;
				}
				int stateWidth = l.fm.stringWidth(state);
				l.text(l.fit(offer.getItemName(), l.width - l.pad - x - stateWidth - 8, l.boldFm), x, baseline, TEXT, l.bold);
				l.textRight(state, l.width - l.pad, baseline, stateColor, l.font);

				int barY = top + l.row + 4;
				int barH = l.row - 10;
				int total = Math.max(1, offer.getTotal());
				Color fill = offer.finished() ? GOOD : offer.cancelled() ? MUTED : offer.isBuying() ? PRAYER : RUN;
				l.bar(x, barY, l.inner() - icon - 6, barH, offer.getDone() / (double) total, fill);
				String progress = DashFormat.commas(offer.getDone()) + " / " + DashFormat.commas(offer.getTotal())
					+ "  @ " + DashFormat.commas(offer.getPrice());
				l.g.setFont(l.small);
				l.g.setColor(Color.WHITE);
				l.g.drawString(l.fit(progress, l.inner() - icon - 12, l.smallFm), x + 4, barY + (barH + l.smallFm.getAscent()) / 2 - 1);
				top += 2 * l.row;
			}
		}
	}

	static final class Alerts extends Tile
	{
		@Override
		String title()
		{
			return "Alerts";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showAlerts();
		}

		@Override
		int height(Layout l)
		{
			return titled(l, Math.max(1, Math.min(l.config.alertCount(), l.snapshot.getAlerts().size())));
		}

		@Override
		void paint(Layout l, int y)
		{
			int top = paintTitle(l, y);
			List<DashSnapshot.Alert> alerts = l.snapshot.getAlerts();
			if (alerts.isEmpty())
			{
				paintEmpty(l, top, "Nothing yet");
				return;
			}
			int shown = Math.min(l.config.alertCount(), alerts.size());
			for (int i = 0; i < shown; i++)
			{
				DashSnapshot.Alert alert = alerts.get(i);
				int baseline = top + i * l.row + l.fm.getAscent() + 2;
				String age = DashFormat.duration(l.now - alert.getAt()) + " ago";
				int ageWidth = l.smallFm.stringWidth(age);
				l.textRight(age, l.width - l.pad, baseline, MUTED, l.small);
				Color color = i == 0 && l.now - alert.getAt() < 60_000 ? TEXT : MUTED;
				l.text(l.fit(alert.getText(), l.inner() - ageWidth - 8, l.fm), l.pad, baseline, color, l.font);
			}
		}
	}

	static final class Timers extends Tile
	{
		@Override
		String title()
		{
			return "Timers and boosts";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showTimers();
		}

		@Override
		int height(Layout l)
		{
			return titled(l, Math.max(1, l.snapshot.getBoxes().size()));
		}

		@Override
		void paint(Layout l, int y)
		{
			int top = paintTitle(l, y);
			List<DashSnapshot.Box> boxes = l.snapshot.getBoxes();
			if (boxes.isEmpty())
			{
				paintEmpty(l, top, "None");
				return;
			}
			int icon = l.row - 2;
			for (DashSnapshot.Box box : boxes)
			{
				int baseline = top + l.fm.getAscent() + 2;
				l.icon(box.getImage(), l.pad, top + 1, icon);
				String value = box.getText() == null ? "" : box.getText();
				int valueWidth = l.boldFm.stringWidth(value);
				l.textRight(value, l.width - l.pad, baseline, box.getTextColor() == null ? TEXT : box.getTextColor(), l.bold);
				int x = l.pad + icon + 6;
				l.text(l.fit(box.getName(), l.width - l.pad - x - valueWidth - 8, l.fm), x, baseline, TEXT, l.font);
				top += l.row;
			}
		}
	}

	static final class Session extends Tile
	{
		@Override
		String title()
		{
			return "Session";
		}

		@Override
		boolean enabled(DashConfig config)
		{
			return config.showSession();
		}

		@Override
		int height(Layout l)
		{
			if (l.snapshot.getSessionStartedAt() == 0) return titled(l, 1);
			return titled(l, 1 + l.snapshot.getTopGains().size());
		}

		@Override
		void paint(Layout l, int y)
		{
			DashSnapshot s = l.snapshot;
			int top = paintTitle(l, y);
			if (s.getSessionStartedAt() == 0)
			{
				paintEmpty(l, top, "Not logged in");
				return;
			}
			int baseline = top + l.fm.getAscent() + 2;
			l.text("Logged in " + DashFormat.duration(l.now - s.getSessionStartedAt()), l.pad, baseline, TEXT, l.font);
			l.textRight(DashFormat.shortNumber(s.getXpGained()) + " xp", l.width - l.pad, baseline, s.getXpGained() > 0 ? GOOD : MUTED, l.bold);
			for (DashSnapshot.SkillGain gain : s.getTopGains())
			{
				baseline += l.row;
				l.text(gain.getSkill(), l.pad, baseline, MUTED, l.font);
				String rate = gain.getPerHour() > 0 ? DashFormat.shortNumber(gain.getPerHour()) + "/h" : "";
				l.textRight(rate, l.width - l.pad, baseline, MUTED, l.small);
				int rateWidth = l.smallFm.stringWidth(rate);
				l.textRight(DashFormat.shortNumber(gain.getGained()), l.width - l.pad - rateWidth - (rate.isEmpty() ? 0 : 10), baseline, TEXT, l.bold);
			}
		}
	}

